@staticmethod
def __stop_plugin(plugin: Any):
    """
        停止插件
        :param plugin: 插件实例
        """
    try:
        if hasattr(plugin, 'close'):
            plugin.close()
        if hasattr(plugin, 'stop_service'):
            plugin.stop_service()
    except Exception as e:
        logger.warn(f'停止插件 {plugin.get_name()} 时发生错误: {str(e)}')

